ExecutorService pool = Executors.newFixedThreadPool(8);
List<Callable<Offer>> tasks = recipients.stream().map(r -> (Callable<Offer>) () -> ask(r)).toList();
List<Future<Offer>> done = pool.invokeAll(tasks, budget, TimeUnit.MILLISECONDS);
List<Offer> offers = new ArrayList<>();
for (Future<Offer> f : done) {
    if (f.isCancelled()) continue;            // deadline reaped this recipient
    try { offers.add(f.get()); } catch (ExecutionException e) { /* per-recipient failure */ }
}

try (var scope = StructuredTaskScope.open(
        StructuredTaskScope.Joiner.anySuccessfulResultOrThrow(),
        cfg -> cfg.withTimeout(budget))) {
    for (Recipient r : recipients) scope.fork(() -> ask(r));
    Offer best = scope.join();     // first success wins; the losers are cancelled by the scope
    return best;
}
